// Generated by Job Route Atlas; run: node scripts/generate.mjs --write | --check
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
const ROOT=path.resolve(path.dirname(fileURLToPath(import.meta.url)),"..");
function esc(s){return String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#39;")}
function renderMermaid(r){
const x=["flowchart TB",`    %% ${r.title} — ${r.last_verified}`];
for(const n of r.nodes)x.push(`    n_${n.id}["${n.label.replace(/"/g,"'").replace(/[|]/g,"／")}"]`);
for(const e of r.edges)x.push(`    n_${e.from} ${e.evidence==="normative"?"-->":"-.->"}|"${e.label.replace(/"/g,"'").replace(/[|]/g,"／")}"| n_${e.to}`);
x.push("    classDef entry fill:#eaf4ff,stroke:#2563eb,color:#1e40af","    classDef role fill:#f0fdfa,stroke:#0d9488,color:#115e59","    classDef target fill:#d1fae5,stroke:#059669,color:#065f46,stroke-width:3px","    classDef milestone fill:#fef3c7,stroke:#d97706,color:#92400e");
for(const n of r.nodes)x.push(`    class n_${n.id} ${n.kind==="entry"?"entry":n.kind==="target"?"target":n.kind==="milestone"?"milestone":"role"}`);
return x.join("\n")+"\n";
}
function renderSvg(r){
const paths=r.pathways, w=paths.length*390+54, max=Math.max(...paths.map(p=>p.node_ids.length)),h=235+max*102;
const out=[`<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" role="img" aria-labelledby="svg-title svg-desc">`,`<title id="svg-title">${esc(r.title)} — 职业路线图</title>`,`<desc id="svg-desc">共 ${paths.length} 条典型或条件性发展路径，箭头不代表保证晋升。</desc>`,
`<rect width="${w}" height="${h}" rx="24" fill="#f7fafc"/>`,`<text x="32" y="46" font-size="25" font-weight="800" fill="#11283f" font-family="Noto Sans SC,Arial,sans-serif">${esc(r.title)}</text>`,`<text x="32" y="77" font-size="14" fill="#587083" font-family="Noto Sans SC,Arial,sans-serif">CAREER PATH MAP   ·   ${esc(r.last_verified)}   ·   条件性路径，不保证晋升</text>`];
const color={entry:["#eaf3ff","#3478d5"],milestone:["#fff4df","#d7a24c"],role:["#e9f7f6","#21948e"],target:["#ddf6e9","#138463"]};
paths.forEach((p,i)=>{
const left=28+i*390,yTop=104,cardW=358,cardH=64,gap=38;
out.push(`<rect x="${left}" y="${yTop}" width="${cardW}" height="${h-yTop-34}" rx="17" fill="#ffffff" stroke="#dce5eb"/>`);
out.push(`<text x="${left+18}" y="${yTop+32}" font-size="18" font-weight="700" fill="#19364b" font-family="Noto Sans SC,Arial,sans-serif">${esc(p.title.length>17?p.title.slice(0,16)+"…":p.title)}</text>`);
p.node_ids.forEach((nodeId,j)=>{
const n=r.nodes.find(n=>n.id===nodeId), y=167+j*(cardH+gap),[fill,stroke]=color[n.kind],x=left+17;
if(j){const prevY=y-gap;out.push(`<path d="M ${left+cardW/2} ${prevY} v ${gap-11}" stroke="#9db0ba" stroke-width="2" stroke-linecap="round" stroke-dasharray="5 5" fill="none"/>`,`<path d="M ${left+cardW/2-5} ${y-12} l5 7 l5 -7" stroke="#9db0ba" stroke-width="1.7" fill="none" stroke-linecap="round" stroke-linejoin="round"/>`)}
out.push(`<rect x="${x}" y="${y}" width="${cardW-34}" height="${cardH}" rx="11" fill="${fill}" stroke="${stroke}" stroke-width="${n.kind==="target"?2:1}"/>`);
out.push(`<rect x="${x+12}" y="${y+17}" width="7" height="30" rx="3.5" fill="${stroke}"/>`);
out.push(`<text x="${x+32}" y="${y+28}" font-size="15" font-weight="700" fill="#18374d" font-family="Noto Sans SC,Arial,sans-serif">${esc(n.label)}</text>`);
out.push(`<text x="${x+32}" y="${y+48}" font-size="11" fill="#526b7a" font-family="Noto Sans SC,Arial,sans-serif">${esc(n.kind==="target"?"目标职务 · 依法选拔":n.kind==="entry"?"进入渠道":n.kind==="role"?"典型岗位 · 非自动晋任":"取得相应身份")}</text>`);
});
});
out.push(`<text x="32" y="${h-12}" font-size="11" fill="#657b89" font-family="Noto Sans SC,Arial,sans-serif">资料来源与证据属性请参阅同目录 route.json / report.md · 虚线箭头表示仅为典型或条件性转换</text>`,"</svg>");
return out.join("\n")+"\n";
}
let changed=[];
for (const category of fs.readdirSync(path.join(ROOT,"data")).sort()) {
  const base=path.join(ROOT,"data",category);
  if (!fs.statSync(base).isDirectory()) continue;
  for(const slug of fs.readdirSync(base).sort()){
    const dir=path.join(base,slug),source=path.join(dir,"route.json");
    if(!fs.statSync(dir).isDirectory()||!fs.existsSync(source))continue;
    const r=JSON.parse(fs.readFileSync(source,"utf8"));
    for(const [file,body] of [["route.mmd",renderMermaid(r)],["route.svg",renderSvg(r)]]){
      const dest=path.join(dir,file),old=fs.existsSync(dest)?fs.readFileSync(dest,"utf8"):null;
      if(old===body)continue;
      changed.push(path.relative(ROOT,dest));
      if(process.argv.includes("--write"))fs.writeFileSync(dest,body,"utf8");
    }
  }
}
if (process.argv.includes("--check") && changed.length) {
 console.error("Generated diagrams out of sync:\n"+changed.join("\n"));process.exitCode=1;
} else console.log((changed.length?changed.join("\n"):"All generated diagrams are current.")+(process.argv.includes("--write")?"\nUpdated.":""));
